using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Text.Json;
namespace DiskLens;
public static class SelfTest {
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool CreateHardLink(string file,string existing,IntPtr reserved);
 public static async Task<int> Run(){var root=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"DiskLens-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var report=new List<string>();void Check(bool ok,string name){if(!ok)throw new Exception("Failed: "+name);report.Add("PASS "+name);}
 try{var paletteEntries=new[]{new Entry("C:\\Users",300,0,"folder"),new Entry("C:\\Windows",100,0,"folder"),new Entry("C:\\Program Files",50,0,"folder"),new Entry("C:\\ExampleData",120,0,"folder")};var palette=MapPalette.FolderColors(paletteEntries);Check(palette.Values.Distinct().Count()==4,"sibling folders have distinct colours");var reordered=MapPalette.FolderColors(paletteEntries.Reverse().Select(e=>e with{Size=1}));Check(palette.All(p=>reordered[p.Key]==p.Value),"folder colours independent of size and ordering");var latest=new ScanInfo("latest","C:\\","2000-01-01T10:00:00Z",0,0,false,"ABCD");var earlier=latest with{Id="earlier",Root="C:",Date="2000-01-01T19:00:00+10:00",VolumeSerial="abcd"};Check(ComparisonSelection.Previous(latest,[latest,earlier])?.Id=="earlier","comparison root/serial normalization and timestamp offsets");Check(ComparisonSelection.Previous(latest,[earlier with{VolumeSerial="OTHER"}])==null,"comparison rejects different volume at same drive letter");await ScanReliabilityTests.Run(root,Check);await DuplicateRegressionTests.Run(root,Check);var source=System.IO.Path.Combine(root,"source");Directory.CreateDirectory(source);File.WriteAllText(System.IO.Path.Combine(source,"setup-test.exe"),"same content");File.WriteAllText(System.IO.Path.Combine(source,"copy.txt"),"same content");Check(CreateHardLink(System.IO.Path.Combine(source,"hardlink.txt"),System.IO.Path.Combine(source,"copy.txt"),IntPtr.Zero),"create hardlink fixture");Directory.CreateDirectory(System.IO.Path.Combine(source,"excluded"));File.WriteAllText(System.IO.Path.Combine(source,"excluded","secret.txt"),"skip");Directory.CreateDirectory(System.IO.Path.Combine(source,"nested","deep"));File.WriteAllText(System.IO.Path.Combine(source,"nested","deep","data.bin"),"12345");
 var store=new Store(System.IO.Path.Combine(root,"store"));var pending=System.IO.Path.Combine(store.Home,"first.pending");var result=await new Scanner().Run(source,pending,true,"*excluded*",new Progress<string>(),CancellationToken.None);Check(result.Files==4,"scanner/exclusions/file totals");store.Commit(result,pending,20);Check(store.History().Count==1,"snapshot publication and persistence");File.WriteAllText(System.IO.Path.Combine(store.Home,"diagnostic-report.json"),"null");var invalidMetadata=System.IO.Path.Combine(store.Home,Guid.NewGuid().ToString("N")+".json");File.WriteAllText(invalidMetadata,"{");Check(store.History().Count==1&&store.HistoryWarning.Contains("could not be loaded"),"invalid metadata is reported without hiding valid snapshots or treating reports as snapshots");File.Delete(invalidMetadata);Check(store.History().Count==1&&store.HistoryWarning.Length==0,"history warning clears after metadata recovery");Check(store.Map(result,source).Sum(x=>x.Size)==result.Bytes,"nested folder aggregation");Check(store.Search(result,"*.exe;*.bin",0,0,"All files").Count==2,"indexed wildcard search");Check(Rules.Installer("setup-test.exe")&&!Rules.Installer("application.exe"),"installer rules");Check(Rules.Explain("C:\\Downloads\\setup.exe",DateTime.UtcNow.Ticks).Contains("Downloads"),"deterministic cleanup explanations");var duplicates=await Duplicates.Find(store,result,"",1,0,new Progress<string>(),CancellationToken.None);Check(duplicates.Count==2,"SHA-256 duplicates and hardlink deduplication");Check(store.Breakdown(result).Sum(e=>e.Size)==result.Bytes,"category totals");DuplicateMetrics? filteredMetrics=null;await Duplicates.Find(store,result,"setup-test.exe",1,0,new Progress<string>(),CancellationToken.None,metrics:m=>filteredMetrics=m);Check(filteredMetrics?.Available==0&&filteredMetrics.Hashed==0,"duplicate filters applied before grouping eliminate singleton hashes");DuplicateMetrics? cappedMetrics=null;await Duplicates.Find(store,result,"",1,0,new Progress<string>(),CancellationToken.None,candidateLimit:2,metrics:m=>cappedMetrics=m);Check(cappedMetrics?.Available==3&&cappedMetrics.Selected==2&&cappedMetrics.Limited,"quick duplicate cap reports remaining candidates");Check((await Duplicates.Find(store,result,"",1,0,new Progress<string>(),CancellationToken.None,true)).Count==0,"installer-only duplicate filter");
 Check((await Duplicates.Find(store,result,"",1,0,new Progress<string>(),CancellationToken.None,category:"Images")).Count==0,"duplicate category filter");File.WriteAllText(System.IO.Path.Combine(source,"copy.txt"),"x");DuplicateMetrics? changedMetrics=null;var changedDuplicates=await Duplicates.Find(store,result,"",1,0,new Progress<string>(),CancellationToken.None,metrics:m=>changedMetrics=m);Check(changedDuplicates.Count==0&&changedMetrics?.Skipped==2,"duplicate check rejects changed file and hard-link alias");using(var duplicateCancellation=new CancellationTokenSource()){duplicateCancellation.Cancel();try{await Duplicates.Find(store,result,"",1,0,new Progress<string>(),duplicateCancellation.Token);throw new Exception("Duplicate cancellation ignored");}catch(OperationCanceledException){Check(true,"duplicate preparation supports cancellation");}}File.WriteAllText(System.IO.Path.Combine(source,"added.txt"),"new file");File.AppendAllText(System.IO.Path.Combine(source,"nested","deep","data.bin"),"grown");File.Delete(System.IO.Path.Combine(source,"setup-test.exe"));File.WriteAllText(System.IO.Path.Combine(source,"copy.txt"),"x");pending=System.IO.Path.Combine(store.Home,"second.pending");var second=await new Scanner().Run(source,pending,false,"*excluded*",new Progress<string>(),CancellationToken.None);store.Commit(second,pending,20);var changes=store.Changes(second,result);Check(changes.Any(e=>e.Detail=="Added")&&changes.Any(e=>e.Detail.StartsWith("Grown"))&&changes.Any(e=>e.Detail.StartsWith("Removed"))&&changes.Any(e=>e.Detail.StartsWith("Shrunk")),"added/grown/shrunk/removed comparison");
 SnapshotLocationTests.Run(root,store,second,result,Check);var precise=InvestigationStore.Changes(store,second,result,CancellationToken.None);Check(precise.Summary.Added>0&&precise.Summary.Grown>0&&precise.Summary.Shrunk>0&&precise.Summary.Removed>0,"full comparison totals for all four changes");Check(precise.Rows.Any(e=>e.Change=="Removed"&&e.Size==0&&e.Delta<0)&&precise.Rows.First().Delta!=0,"comparison current size and signed differences");
 using(var db=new Db(store.PathFor(second))){db.Exec($"INSERT INTO files VALUES('C:\\fixture\\photo.png','C:\\fixture',2097152,{DateTime.UtcNow.Ticks},'.png'); INSERT INTO files VALUES('C:\\fixture\\archive.zip','C:\\fixture',4194304,{DateTime.UtcNow.Ticks},'.zip'); INSERT INTO files VALUES('C:\\fixture\\package.pkg','C:\\fixture',4194304,{DateTime.UtcNow.Ticks},'.pkg'); INSERT INTO files VALUES('C:\\fixture\\node_modules\\old.bin','C:\\fixture',3145728,{DateTime.UtcNow.AddDays(-200).Ticks},'.bin');");}
 Check(InvestigationStore.Files(store,second,"Archives and images","",0,0,0,CancellationToken.None).Count==2,"archives and images preset excludes installers");Check(InvestigationStore.Files(store,second,"Developer clutter","",0,0,0,CancellationToken.None).Any(e=>e.Path.Contains("node_modules")),"developer clutter deterministic preset");Check(InvestigationStore.Files(store,second,"Old large files","",0,0,0,CancellationToken.None).Count==1,"old large file age and size threshold");Check(InvestigationStore.Files(store,second,"Recent large files","",0,0,0,CancellationToken.None).Count==3,"recent large file age and size threshold");
 foreach(var ext in new[]{"csv","html","json"}){var p=System.IO.Path.Combine(root,"export."+ext);Actions.Export(p,[new Entry("=a\"<&",42,0,"file","reason")]);Check(new FileInfo(p).Length>0,"export "+ext);if(ext=="json")Check(JsonDocument.Parse(File.ReadAllText(p)).RootElement.GetArrayLength()==1,"valid JSON export");if(ext=="html")Check(File.ReadAllText(p).Contains("&lt;"),"HTML escaping");if(ext=="csv")Check(File.ReadAllText(p).Contains("'=a"),"CSV formula protection");}
 using(var cts=new CancellationTokenSource()){cts.Cancel();try{await new Scanner().Run(source,System.IO.Path.Combine(store.Home,"cancel.pending"),false,"",new Progress<string>(),cts.Token);throw new Exception("Cancellation failed");}catch(OperationCanceledException){Check(store.History().Count==2,"cancel preserves previous completed snapshots");}}
 Process Slow()=>Process.Start(new ProcessStartInfo("powershell.exe","-NoProfile -NonInteractive -Command \"Start-Sleep -Seconds 30\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true})!;
 var sw=Stopwatch.StartNew();try{await new Scanner(500,Slow).Run(source,System.IO.Path.Combine(store.Home,"timeout.pending"),false,"",new Progress<string>(),CancellationToken.None);throw new Exception("Timeout failed");}catch(IOException){Check(sw.Elapsed<TimeSpan.FromSeconds(8),"blocked worker killed within bounded deadline");}
 using(var db=new Db(store.PathFor(second))){db.Exec("BEGIN; WITH RECURSIVE n(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM n WHERE x<1000000) INSERT INTO files SELECT 'C:\\synthetic\\file-'||x||'.bin','C:\\synthetic',x,0,'.bin' FROM n; COMMIT;");}sw.Restart();var page=store.Search(second,"file-",0,0,"All files");Check(page.Count==500,"million-row index bounded search page");report.Add($"METRIC million-row first-page query {sw.Elapsed.TotalMilliseconds:N0} ms; peak working set {Process.GetCurrentProcess().PeakWorkingSet64:N0} bytes; index {new FileInfo(store.PathFor(second)).Length:N0} bytes");
 try{Actions.Recycle(new Entry(System.IO.Path.Combine(source,"copy.txt"),999,0,"file"));throw new Exception("Unsafe cleanup allowed");}catch(IOException){Check(true,"changed-file cleanup rejected before native dialog");}
 File.WriteAllLines(System.IO.Path.Combine(AppContext.BaseDirectory,"self-test-result.txt"),report);return 0;
 }catch(Exception e){report.Add(e.ToString());File.WriteAllLines(System.IO.Path.Combine(AppContext.BaseDirectory,"self-test-result.txt"),report);return 1;}finally{Directory.Delete(root,true);}}
}




